sql.where:
m.delete_flag = FALSE
AND m.deleted_at IS NULL
AND m.status = 'ACTIVE'

    AND m.project_id = #{projectId}


    AND m.repository_id = #{repositoryId}


    AND m.ticket_id = #{ticketId}


    AND (t.external_ticket_key ILIKE CONCAT('%', #{search}, '%')
         OR t.title ILIKE CONCAT('%', #{search}, '%'))
